    a, b = ti[rows], tj[rows]
    m = ~(np.isnan(a) | np.isnan(b))
    return np.corrcoef(a[m], b[m])[0, 1]

for label, rows in [("full", slice(None)), ("last250", slice(-250, None)), ("last60", slice(-60, None))]:
