for s in OBS: data[s] = load(f'../persistent/index_data/{s}.csv')

def rets(series, n):
    ds = sorted(series.keys()); out = {}
    for i in range(n, len(ds)): out[ds[i]] = series[ds[i]]/series[ds[i-n]]-1.0
    return out

def daily_rets(series):
    ds = sorted(series.keys()); out = {}
    for i in range(1, len(ds)): out[ds[i]] = series[ds[i]]/series[ds[i-1]]-1.0
    return out

def vol_ann(series, n=20):
    dr = daily_rets(series); ds = sorted(dr.keys()); out = {}
    for i in range(n, len(ds)):
        win = [dr[ds[j]] for j in range(i-n, i)]
        m = sum(win)/len(win); v = sum((x-m)**2 for x in win)/(len(win)-1)
        out[ds[i]] = math.sqrt(v)*math.sqrt(252)
    return out

def ma(series, n):
    ds = sorted(series.keys()); out = {}; s = 0.0
    for i, d in enumerate(ds):
        s += series[d]
        if i >= n: s -= series[ds[i-n]]
        if i >= n-1: out[d] = s/n
    return out

def last_ret(s, n):
