import json, numpy as np, os
from scipy.stats import spearmanr

sel = ['max_consec_gain_20','mom20_volproxy60','spx_corr60','mom_20d_skip5','gain_loss_20','downbeta_spx_60','usdjpy_beta_cond_120x60','volcluster_60','calmness_20']

panels = {}
for fid in sel:
    npy = f'factors/{fid}.signal.npy'
    if os.path.exists(npy):
        arr = np.load(npy)
        panels[fid] = arr
        print(f'{fid}: npy shape {arr.shape}', arr.dtype)
    else:
        d = json.load(open(f'factors/{fid}.json'))
        emb = d.get('signal_artifact', {}).get('daily_panel') if isinstance(d.get('signal_artifact'), dict) else None
        if emb is not None:
            panels[fid] = np.array(emb)
            print(f'{fid}: embedded daily_panel shape {np.array(emb).shape}')
        else:
            print(f'{fid}: NO panel available')

lens = {k: v.shape for k, v in panels.items()}
print('shapes:', lens)

# Flatten each panel (dates x assets) -> vector, then spearman
names = sorted(panels.keys())
vecs = {}
for fid in names:
    a = np.asarray(panels[fid], dtype=float)
    if a.ndim == 2:
        # use last 500 rows to focus on recent regime
        a = a[-500:]
    vecs[fid] = a.flatten()

print('\nPairwise |Spearman rho| (recent 500d flattened):')
hdr = '        ' + ' '.join(f'{x[:8]:>9}' for x in names)
print(hdr)
maxp = {}
for a in names:
    cells = []
    for b in names:
        if a == b:
            cells.append('    -    '); continue
        va, vb = vecs[a], vecs[b]
        if len(va) != len(vb):
            cells.append('  n/a    '); continue
        r = abs(float(spearmanr(va, vb).statistic))
        cells.append(f'{r:9.3f}')
        maxp[a] = max(maxp.get(a, 0.0), r)
    print(f'{a[:8]:>8}' + ' '.join(cells))

print('\nMax pairwise |rho| per factor (recent 500d):')
for a in names:
    print(f'  {a}: {maxp.get(a, float("nan")):.3f}')
viol = [(a, round(maxp[a],3)) for a in names if maxp.get(a,0) >= 0.5]
print('\nViolations (>=0.5):', viol if viol else 'NONE')
