python << 'EOF'
import json, glob, os
import numpy as np
files = sorted(glob.glob('factors/*.json'))
canon = [f for f in files if os.path.basename(f).count('.') == 1 and 'factor_ensemble' not in f]
for f in sorted(canon):
    d = json.load(open(f))
    art = d.get('signal_artifact')
    if isinstance(art, dict):
        print(f"{os.path.basename(f).replace('.json',''):<28} signal_artifact dict: {str(art)[:120]}")
        continue
    if art:
        p = art if os.path.exists(art) else os.path.join('factors', os.path.basename(art))
        if os.path.exists(p):
            try:
                a = np.load(p, allow_pickle=True)
                print(f"{os.path.basename(f).replace('.json',''):<28} npy shape={a.shape}")
            except Exception as e:
                print(os.path.basename(f), 'npy err', e)
        else:
            print(f"{os.path.basename(f).replace('.json',''):<28} artifact MISSING: {art}")
    else:
        sig = d.get('signal')
        dp = sig.get('daily_panel') if isinstance(sig, dict) else None
        if dp:
            dates = dp.get('dates', [])
            print(f"{os.path.basename(f).replace('.json',''):<28} embedded panel dates n={len(dates)} last={dates[-1] if dates else '?'}")
        else:
            print(f"{os.path.basename(f).replace('.json',''):<28} no artifact / no panel")
EOF

