import json, glob, re

def get_regime_ic(d):
    rn = d.get('validation', {}).get('regime_notes', None)
    if isinstance(rn, dict):
        out = {}
        for k, v in rn.items():
            if isinstance(v, dict) and 'ic' in v:
                out[k] = v['ic']
        return out
    if isinstance(rn, str):
        # parse ic=+0.2121 icir=+0.608 n=445 patterns per year-block
        out = {}
        for m in re.finditer(r'(\d{4}-\d{2}|\d{4}-\d{4}|\d{4}):\s*ic=([+-]?[\d.]+)\s+icir=([+-]?[\d.]+)\s+n=(\d+)', rn):
            out[m.group(1)] = float(m.group(2))
        # last250 pattern
        m2 = re.search(r'last250:ic=([+-]?[\d.]+)', rn)
        if m2:
            out['last250'] = float(m2.group(1))
        return out
    return {}

files = sorted(glob.glob('factors/*.json'))
files = [f for f in files if 'ensemble' not in f and '.bak' not in f]
for f in files:
    try:
        with open(f) as fh:
